const [lojaId, setLojaId] = useState<number | null>(null);
const [formaPagamento, setFormaPagamento] = useState<string>('boleto');
const [creditCardId, setCreditCardId] = useState<number | null>(null);

useEffect(() => {
  if (isOpen && initialData) {
    setData(initialData);
  } else if (isOpen && !initialData) {
    setData({ numero_nota: '', fornecedor: '', data_nota: '', data_vencimento: '', data_recebimento: '', valor_total: 0, itens: [] });
  }
  if (isOpen) {
    setLojaId(selectedStoreId || null);
    setFormaPagamento('boleto');
    setCreditCardId(null);
  }
}, [isOpen, initialData, selectedStoreId]);

const handleSave = async () => {
  if (!data.fornecedor) {
    toast.error('Preencha o fornecedor.');
    return;
  }
  // R4: quando há seletor de loja visível (stores disponíveis), exige loja escolhida
  if (stores.length > 0 && !lojaId) {
    toast.error('Selecione uma loja para lançar a nota.');
    return;
  }
  await onSave(data, {
    lojaIdOverride: lojaId,
    formaPagamento: formaPagamento || null,
    creditCardId: formaPagamento === 'cartao_credito' ? creditCardId : null,
  });
};

const updateItem = (index: number, field: string, value: any) => {
  const newItens = [...(data.itens || [])];
  const currentItem = { ...newItens[index], [field]: value };

  // Auto-calculate subtotal if quantity or unit price changes
  if (field === 'quantidade' || field === 'valor_unitario') {
    const qty =
      field === 'quantidade'
        ? parseFloat(value)
        : parseFloat(currentItem.quantidade);
    const price =
      field === 'valor_unitario'
        ? parseFloat(value)
        : parseFloat(currentItem.valor_unitario);

    if (!isNaN(qty) && !isNaN(price)) {
      currentItem.subtotal = parseFloat((qty * price).toFixed(2));
    }
  }

  newItens[index] = currentItem;

  // Optional: Update total invoice value based on items sum
  const newTotal = newItens.reduce(
    (sum: number, item: any) => sum + (parseFloat(item.subtotal) || 0),
    0,
  );

  setData({ ...data, itens: newItens, valor_total: newTotal });
};

const addItem = () => {
  setData({
    ...data,
    itens: [
      ...(data.itens || []),
      {
        nome_produto: '',
        quantidade: 0,
        valor_unitario: null,
        subtotal: null,
        categoria: '',
      },
    ],
  });
};

const removeItem = (index: number) => {
  const newItens = [...(data.itens || [])];
  newItens.splice(index, 1);

  // Recalculate total when item is removed
  const newTotal = newItens.reduce(
    (sum: number, item: any) => sum + (parseFloat(item.subtotal) || 0),
    0,
  );

  setData({ ...data, itens: newItens, valor_total: newTotal });
};

return (
  <Dialog
    open={isOpen}
    onOpenChange={(open) => !open && onClose()}

