// Insert or Update
// Se tiver selectedNota?.id, é update.
let notaId = selectedNota?.id;

dataToSave.data_nota = dataToSave.data_nota || null;
dataToSave.data_vencimento = dataToSave.data_vencimento || null;
dataToSave.data_recebimento = dataToSave.data_recebimento || null;

if (notaId) {
  // Update — não bloqueia edição mesmo sem loja local resolvida (nota já tem loja_id)
  const lojaId = options?.lojaIdOverride ?? (canSelectStoreNF() ? (comprasLojaId !== 'all' ? comprasLojaId : undefined) : selectedStore?.id);
  const { error: updateError } = await supabase
    .from('notas_fiscais')
    .update({
      numero_nota: dataToSave.numero_nota,
      fornecedor: dataToSave.fornecedor,
      cnpj_emitente: dataToSave.cnpj_emitente || null,
      endereco_emitente: dataToSave.endereco_emitente || null,
      data_nota: dataToSave.data_nota,
      data_vencimento: dataToSave.data_vencimento || null,
      data_recebimento: dataToSave.data_recebimento || null,
      valor_total: dataToSave.valor_total,
      imagem_url: fotoUrl,
      imagem_url_2: fotoUrl2,
      loja_id: lojaId,
      forma_pagamento: options?.formaPagamento || null,
      credit_card_id: options?.formaPagamento === 'cartao_credito' && options?.creditCardId ? options.creditCardId : null,
    })
    .eq('id', notaId);

  if (updateError) throw updateError;

  // Para itens, deletamos e recriamos ou atualizamos?
  // Abordagem simples: deletar todos antigos e inserir novos.
  const { error: delError } = await supabase.from('itens_nota_fiscal').delete().eq('nota_id', notaId);
  if (delError) throw delError;

  // Auto-sync update: route to card or contas_pagar
  try {
    if (dataToSave.valor_total) {
      const isCartao = options?.formaPagamento === 'cartao_credito' && options?.creditCardId;

      if (isCartao) {
        // Remove contas_pagar (may exist if switching from boleto to card)
        await supabase.from('contas_pagar_receber').delete().eq('nota_fiscal_id', notaId);
        // Delete old card transaction and re-create with correct loja
        await supabase.from('credit_card_transactions').delete().eq('nota_fiscal_id', notaId);

        const cardId = options.creditCardId!;

