import { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { useAuth } from './useAuth';
import { supabase } from '@/integrations/supabase/client';
import { wideError } from '@/shared/lib/telemetry/wide-events';
import { handleError } from '@/shared/lib/error-handler';

interface Permission {
  permission_name: string;
  permission_display_name: string;
  module: string;
}

interface UserRole {
  role_name: string;
  role_display_name: string;
  can_change_store: boolean;
}

interface PermissionsContextType {
  permissions: Permission[];
  userRole: UserRole | null;
  loading: boolean;
  hasPermission: (permissionName: string) => boolean;
  hasAnyPermission: (permissionNames: string[]) => boolean;
  isAdmin: () => boolean;
  canAccessModule: (module: string) => boolean;
  refreshPermissions: () => Promise<void>;
  canViewFinanceiro: () => boolean;
  canViewDashboard: () => boolean;
  canViewEstoque: () => boolean;
  canAdminPermissions: () => boolean;
  canViewLogistica: () => boolean;
  canViewRequisicao: () => boolean;
  canViewNotasFiscais: () => boolean;
  canViewEncomendas: () => boolean;
  canViewNCM: () => boolean;
  canViewEventos: () => boolean;
  canViewProntaEntrega: () => boolean;
  canViewMia: () => boolean;
  canSwitchStore: () => boolean;
  canSelectStoreNF: () => boolean;
}

const PermissionsContext = createContext<PermissionsContextType | undefined>(undefined);

export function PermissionsProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const [permissions, setPermissions] = useState<Permission[]>([]);
  const [userRole, setUserRole] = useState<UserRole | null>(null);
  const [profileSelectStoreNF, setProfileSelectStoreNF] = useState<boolean>(false);
  const [loading, setLoading] = useState(true);

  const fetchUserPermissions = async () => {
    if (!user) {
      setPermissions([]);
      setUserRole(null);
      setProfileSelectStoreNF(false);
      setLoading(false);
      return;
    }

import '@testing-library/jest-dom';
import { vi } from 'vitest';

// Mock de window.matchMedia para jsdom (usado por useIsMobile e componentes responsivos)
Object.defineProperty(window, 'matchMedia', {
  writable: true,
  value: vi.fn().mockImplementation((query: string) => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: vi.fn(), // deprecated
    removeListener: vi.fn(), // deprecated
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: vi.fn(),
  })),
});

// Mock do ResizeObserver
global.ResizeObserver = class {
  observe() {}
  unobserve() {}
  disconnect() {}
};

// Mock global do cliente Supabase para todos os testes unitários
// Chainable builder: cada método retorna o próprio builder, permitindo qualquer
// combinação de .from().select().eq().single() etc.
vi.mock('@/integrations/supabase/client', () => {
  const builder: Record<string, any> = {};
  const chainMethods = [
    'from', 'select', 'insert', 'update', 'upsert', 'delete',
    'eq', 'neq', 'gt', 'gte', 'lt', 'lte', 'like', 'ilike',
    'is', 'in', 'not', 'or', 'filter', 'match',
    'order', 'limit', 'range', 'single', 'maybeSingle',
    'csv', 'returns',
  ];
  for (const m of chainMethods) {
    builder[m] = vi.fn().mockReturnValue(builder);
  }
  builder.then = vi.fn((resolve: any) => resolve({ data: [], error: null }));
  return {
    supabase: {
      ...builder,
      rpc: vi.fn().mockResolvedValue({ data: [], error: null }),
      auth: {
        getUser: vi.fn(),
        signInWithPassword: vi.fn(),
        signOut: vi.fn(),
        getSession: vi.fn().mockResolvedValue({ data: { session: null }, error: null }),
        refreshSession: vi.fn().mockResolvedValue({ data: { session: null }, error: null }),
        onAuthStateChange: vi.fn(() => ({ data: { subscription: { unsubscribe: vi.fn() } } })),
      },
      channel: vi.fn().mockReturnValue({
        on: vi.fn().mockReturnThis(),
        subscribe: vi.fn(),
      }),
      removeChannel: vi.fn(),
    },
    SESSION_UNAUTHORIZED_EVENT: 'supabase:unauthorized',
  };
});

// Mock global do useTelemetryAttrs — hook de observabilidade que depende de
// useLocation, useAuth e useStore. Retorna objeto vazio em testes.
vi.mock('@/shared/lib/telemetry/useTelemetryAttrs', () => ({
  useTelemetryAttrs: () => ({}),
}));

// Mock global do MiaContext — evita que MiaProvider precise de StoreProvider
// real. Testes específicos de MIA fazem override local.
vi.mock('@/shared/contexts/MiaContext', () => ({
  MiaProvider: ({ children }: any) => children,
  useMia: () => ({
    messages: [],
    isStreaming: false,
    streamingStatus: '',
    sendMessage: vi.fn(),
    clearConversation: vi.fn(),
    conversations: [],
    activeConversationId: null,
    setActiveConversationId: vi.fn(),
    createConversation: vi.fn(),
    deleteConversation: vi.fn(),
    renameConversation: vi.fn(),
    registerActions: vi.fn(),
    unregisterActions: vi.fn(),
  }),
  useMiaGlassBoxContext: () => ({
    miaModeEnabled: false,
    toggleMiaMode: vi.fn(),
    setMiaModeEnabled: vi.fn(),
    paneSize: 33,
    setPaneSize: vi.fn(),
    autonomyMode: 'assistido',
    setAutonomyMode: vi.fn(),
    currentPageModel: null,
    setCurrentPageModel: vi.fn(),
    watchLog: [],
    addWatchLogEntry: vi.fn(),
    clearWatchLog: vi.fn(),
    finalizeOrphanedEntries: vi.fn(),
    currentHighlight: null,
    highlightElement: vi.fn(),
    clearHighlight: vi.fn(),
    cursorPosition: null,
    moveCursor: vi.fn(),
    isExecuting: false,
    isPaused: false,
    setPaused: vi.fn(),
    pausedIntent: null,
    savePausedIntent: vi.fn(),
    clearPausedIntent: vi.fn(),
    recordedActions: [],
    recordAction: vi.fn(),
    clearRecordedActions: vi.fn(),
  }),
}));

// Mock global de wide-events — telemetria não deve interferir em testes
vi.mock('@/shared/lib/telemetry/wide-events', () => ({
  wideInfo: vi.fn(),
  wideDebug: vi.fn(),
  wideWarn: vi.fn(),
  wideError: vi.fn(),
}));

// Mock global de metrics — telemetria não deve interferir em testes
vi.mock('@/shared/lib/telemetry/metrics', () => ({
  initMetrics: vi.fn(),
  recordUserLogin: vi.fn(),
  recordUserLogout: vi.fn(),
  recordOperation: vi.fn(),
  recordError: vi.fn(),
  recordDuration: vi.fn(),
  recordOperationDuration: vi.fn(),
  recordRequisition: vi.fn(),
  recordExpedition: vi.fn(),
  recordOrder: vi.fn(),
  recordOrderStatusTransition: vi.fn(),
  recordFinancialTransaction: vi.fn(),
  recordProductionRecord: vi.fn(),
  recordSearchQuery: vi.fn(),
  recordSearchEmpty: vi.fn(),
  recordChartRenderDuration: vi.fn(),
  recordPageDwellDuration: vi.fn(),
  recordStoreChange: vi.fn(),
  recordStoreChangeDuration: vi.fn(),
}));

// Mock global de rum — telemetria não deve interferir em testes
vi.mock('@/shared/lib/telemetry/rum', () => ({
  rumSessionStart: vi.fn(),
  rumSessionEnd: vi.fn(),
  recordRumStoreChange: vi.fn(),
  recordRumPageDwell: vi.fn(),
}));

// Mock global do useChartPerformance — depende de useLocation
vi.mock('@/shared/lib/telemetry/useChartPerformance', () => ({
  useChartPerformance: vi.fn(),
}));

// Mock global do error-handler — evita side effects em testes
vi.mock('@/shared/lib/error-handler', () => ({
  handleError: vi.fn(),
  AppError: class AppError extends Error {
    code: string;
    constructor(code: string, message: string) {
      super(message);
      this.code = code;
    }
  },
}));

