33	    ilike: vi.fn().mockReturnThis(),
34	    order: vi.fn().mockReturnThis(),
35	    limit: vi.fn().mockReturnThis(),
36	    range: vi.fn().mockReturnThis(),
37	    single: vi.fn().mockResolvedValue({ data: returnData[0] ?? null, error: returnError }),
38	    maybeSingle: vi.fn().mockResolvedValue({ data: returnData[0] ?? null, error: returnError }),
39	    // then síncrono: chama o resolve imediatamente, retorna Promise para await funcionar
40	    then: vi.fn().mockImplementation((resolve: any, reject?: any) => {
41	      try {
42	        const resolved = resolve(result);
43	        return Promise.resolve(resolved);
44	      } catch (e) {
45	        return reject ? Promise.reject(e).catch(reject) : Promise.reject(e);
46	      }
47	    }),
48	    catch: vi.fn().mockImplementation((_reject: any) => Promise.resolve(result)),
49	    finally: vi.fn().mockImplementation((cb: any) => { cb(); return Promise.resolve(result); }),
50	  };
51	  return mockChain;
52	};
