/**
 * sanitizeDate: If date is >60 days in the future and day ≤ 12,
 * try swapping DD↔MM to fix BR↔US date mismatches.
 */
function sanitizeDate(dateStr: string | null | undefined): string | null {
    if (!dateStr) return null;
    const match = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!match) return dateStr;

    const [, yearStr, monthStr, dayStr] = match;
    const year = parseInt(yearStr);
    const month = parseInt(monthStr);
    const day = parseInt(dayStr);

    const parsed = new Date(year, month - 1, day);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const diffMs = parsed.getTime() - today.getTime();
    const diffDays = diffMs / (1000 * 60 * 60 * 24);

    if (diffDays > 60 && day <= 12) {
        const swapped = new Date(year, day - 1, month);
        const swappedDiff =
            (swapped.getTime() - today.getTime()) / (1000 * 60 * 60 * 24);
        if (swappedDiff <= 60) {
            return `${yearStr}-${dayStr}-${monthStr}`;
        }
    }
    return dateStr;
}

/**
 * normalizeItems: Merges duplicate products by name (case-insensitive).
 * Accumulates quantities and subtotals. Calculates unit price if missing.
 */
