it('renders without crashing', async () => {
  const { default: NotasFiscais } = await import('./NotasFiscais.page');
  render(<NotasFiscais />);
  expect(document.body).toBeTruthy();
});

it('fetches notas on mount and displays them', async () => {
  // Mock de dados de notas
  const mockNotas = [
    createMockNota({ id: '1', numero_nota: 'NF-001' }),
    createMockNota({ id: '2', numero_nota: 'NF-002', status: 'processando' }),
    createMockNota({ id: '3', numero_nota: 'NF-003', fornecedor: 'Outro Fornecedor' }),
  ];

  // Mock do Supabase para retornar os dados
  const mockChain = createSupabaseMock(mockNotas);
  vi.mocked(supabase.from).mockImplementation(() => mockChain);

  const { default: NotasFiscais } = await import('./NotasFiscais.page');
  render(<NotasFiscais />);

  // Verifica se a query foi chamada
  await waitFor(() => {
    expect(supabase.from).toHaveBeenCalledWith('notas_fiscais');
  });

